import type { Invoice, OrderItem } from "../operations/operations.types";

/**
 * Approved invoice document boundary.
 * Source sample: VENDOME_INVOICE_A5_POTRAIT.PDF
 * Source PDF SHA-256: ce205f8fafebaed609ff1093c43be2abcce83531989b5eb23461f078f881393f
 * The visual background below is a print-optimized WebP rendered from that approved PDF.
 *
 * Per Phase 7C-A, order/payment issuance, correction, print-job logging and desktop
 * orchestration stay unchanged. Only this document-template boundary controls the
 * approved field mapping, pagination and A5 print layout.
 */
const APPROVED_A5_TEMPLATE = "data:image/webp;base64,";

const ITEMS_PER_PAGE = 6;
const rialFormatter = new Intl.NumberFormat("fa-IR", { maximumFractionDigits: 0 });
const decimalFormatter = new Intl.NumberFormat("fa-IR", { maximumFractionDigits: 3 });
const dateFormatter = new Intl.DateTimeFormat("fa-IR-u-ca-persian", {
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});

function escapeHtml(value: unknown): string {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function optional(value?: string | null): string {
  return value?.trim() ? escapeHtml(value.trim()) : "";
}

function number(value?: number | null): string {
  return value == null ? "" : rialFormatter.format(value);
}

function decimal(value?: number | null): string {
  return value == null ? "" : decimalFormatter.format(value);
}

function statusLabel(status: string): string {
  if (status === "Voided") return "باطل‌شده";
  if (status === "Issued") return "صادرشده";
  return escapeHtml(status);
}

function addressText(invoice: Invoice): string {
  const address = invoice.address;
  if (!address) return "";
  return [address.province, address.city, address.addressLine]
    .filter((part) => part?.trim())
    .map((part) => part!.trim())
    .join("، ");
}

function itemRow(item: OrderItem | undefined, absoluteIndex: number): string {
  if (!item) {
    return '<div class="item-row">' + '<span></span>'.repeat(10) + '</div>';
  }

  return `<div class="item-row">
    <span>${number(item.lineTotalRials)}</span>
    <span>${number(item.unitPriceRials)}</span>
    <span>${number(item.quantity)}</span>
    <span>${decimal(item.netGoldWeightGrams)}</span>
    <span>${decimal(item.grossWeightGrams)}</span>
    <span>${number(item.karat)}</span>
    <span class="compact">${optional(item.variantName)}</span>
    <span class="compact">${optional(item.productName)}</span>
    <span class="ltr compact">${optional(item.sku)}</span>
    <span>${rialFormatter.format(absoluteIndex + 1)}</span>
  </div>`;
}

function pageItems(invoice: Invoice, pageIndex: number): string {
  const start = pageIndex * ITEMS_PER_PAGE;
  const rows = Array.from({ length: ITEMS_PER_PAGE }, (_, rowIndex) =>
    itemRow(invoice.items[start + rowIndex], start + rowIndex),
  );
  return rows.join("");
}

function pageHtml(invoice: Invoice, pageIndex: number, pageCount: number): string {
  const store = invoice.store;
  const address = invoice.address;
  const isLastPage = pageIndex === pageCount - 1;
  const isVoided = invoice.status === "Voided";
  const continuationNote = !isLastPage
    ? `ادامه اقلام فاکتور - صفحه ${rialFormatter.format(pageIndex + 1)} از ${rialFormatter.format(pageCount)}`
    : isVoided && invoice.voidReason
      ? `فاکتور باطل شده است. دلیل: ${escapeHtml(invoice.voidReason)}`
      : "";

  // Invoice does not currently expose authoritative payment method/trace/date snapshots.
  // Those cells intentionally remain blank instead of inventing transaction data.
  return `<main class="page">
    ${isVoided ? '<div class="void-watermark">باطل‌شده</div>' : ""}

    <div class="field meta-value ltr" style="top:3.20%">${optional(invoice.invoiceNumber)}</div>
    <div class="field meta-value" style="top:6.35%">${escapeHtml(dateFormatter.format(new Date(invoice.issuedAt)))}</div>
    <div class="field meta-value" style="top:9.45%">${statusLabel(invoice.status)}</div>
    <div class="field meta-value ltr" style="top:12.55%">${escapeHtml(invoice.orderId.slice(0, 8).toUpperCase())}</div>

    <div class="field customer" style="top:20.55%">${optional(invoice.customerNameSnapshot)}</div>
    <div class="field customer ltr" style="top:23.45%">${optional(invoice.customerNationalIdSnapshot)}</div>
    <div class="field customer ltr" style="top:26.15%">${optional(address?.phoneNumber)}</div>
    <div class="field customer wrap" style="top:28.80%;height:5.4%">${escapeHtml(addressText(invoice))}</div>

    <div class="field store" style="top:19.55%">${optional(store?.tradeName)}</div>
    <div class="field store" style="top:21.55%">${optional(store?.legalName)}</div>
    <div class="field store ltr" style="top:23.55%">${optional(store?.nationalId)}</div>
    <div class="field store ltr" style="top:25.55%">${optional(store?.economicCode)}</div>
    <div class="field store ltr" style="top:27.55%">${optional(store?.registrationNumber)}</div>
    <div class="field store ltr" style="top:29.55%">${optional(store?.phoneNumber)}</div>
    <div class="field store ltr" style="top:31.55%">${optional(store?.postalCode)}</div>
    <div class="field store wrap" style="top:33.35%;height:3.4%">${optional(store?.addressLine)}</div>

    <div class="unit-price-header">قیمت واحد<br />(ریال)</div>
    <div class="items-overlay">${pageItems(invoice, pageIndex)}</div>

    ${isLastPage ? `
      <div class="field total-value" style="top:65.15%">${number(invoice.subtotalRials)}</div>
      <div class="field total-value" style="top:67.55%">${number(invoice.discountRials)}</div>
      <div class="field total-value" style="top:69.95%">${number(invoice.shippingRials)}</div>
      <div class="field total-value grand" style="top:72.60%">${number(invoice.grandTotalRials)}</div>
    ` : ""}

    <div class="field note">${continuationNote}</div>
  </main>`;
}

export function invoiceFileName(invoice: Invoice): string {
  return `Vendome-${invoice.invoiceNumber.replaceAll(/[^a-zA-Z0-9_-]/g, "-")}.pdf`;
}

export function buildInvoiceDocumentHtml(invoice: Invoice): string {
  const pageCount = Math.max(1, Math.ceil(invoice.items.length / ITEMS_PER_PAGE));
  const pages = Array.from({ length: pageCount }, (_, pageIndex) =>
    pageHtml(invoice, pageIndex, pageCount),
  ).join("");

  return `<!doctype html>
<html lang="fa" dir="rtl">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>فاکتور ${escapeHtml(invoice.invoiceNumber)}</title>
  <style>
    @page { size: 148mm 210mm; margin: 0; }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; background: #e7e9ed; color: #132a4b; }
    body {
      font-family: Tahoma, "Segoe UI", Arial, sans-serif;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
    .page {
      position: relative;
      width: 148mm;
      height: 210mm;
      margin: 7mm auto;
      overflow: hidden;
      background-color: #fff;
      background-image: url("${APPROVED_A5_TEMPLATE}");
      background-position: center;
      background-repeat: no-repeat;
      background-size: 100% 100%;
      box-shadow: 0 10px 34px rgba(13, 27, 48, .16);
      break-after: page;
      page-break-after: always;
    }
    .page:last-child { break-after: auto; page-break-after: auto; }
    .field {
      position: absolute;
      color: #132a4b;
      font-size: 2.05mm;
      font-weight: 600;
      line-height: 1.3;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .ltr { direction: ltr; unicode-bidi: plaintext; }
    .wrap { white-space: normal; line-height: 1.5; text-overflow: clip; }
    .meta-value { left: 3.0%; width: 14.4%; text-align: center; font-size: 1.92mm; }
    .customer { left: 5.3%; width: 31.0%; text-align: right; }
    .store { left: 51.4%; width: 32.2%; text-align: right; font-size: 1.88mm; }
    .unit-price-header {
      position: absolute;
      left: 12.92%;
      top: 40.08%;
      width: 10.72%;
      height: 3.22%;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: .25mm;
      color: #fff;
      background: #102d52;
      font-size: 1.46mm;
      font-weight: 700;
      line-height: 1.1;
      text-align: center;
    }
    .items-overlay {
      position: absolute;
      left: 2.95%;
      top: 43.35%;
      width: 94.05%;
      height: 15.25%;
      display: grid;
      grid-template-rows: repeat(6, 1fr);
      direction: ltr;
    }
    .item-row {
      display: grid;
      grid-template-columns: 10.2fr 10.8fr 6.8fr 10.4fr 9.8fr 7.2fr 11.5fr 10.8fr 12.5fr 10fr;
      align-items: center;
      color: #132a4b;
      font-size: 1.62mm;
      font-weight: 600;
      text-align: center;
    }
    .item-row span {
      min-width: 0;
      padding: 0 .45mm;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
      direction: rtl;
    }
    .item-row span.ltr { direction: ltr; }
    .item-row span.compact { font-size: 1.52mm; }
    .total-value { left: 5.2%; width: 29.0%; text-align: center; font-size: 1.92mm; }
    .total-value.grand { font-size: 2.50mm; font-weight: 800; }
    .note {
      left: 5.4%;
      top: 77.2%;
      width: 87.0%;
      height: 4.4%;
      white-space: normal;
      font-size: 1.70mm;
      line-height: 1.45;
      text-align: right;
    }
    .void-watermark {
      position: absolute;
      top: 46%;
      right: 13%;
      z-index: 4;
      color: rgba(146, 44, 44, .18);
      font-size: 15mm;
      font-weight: 900;
      transform: rotate(-22deg);
      pointer-events: none;
    }
    @media print {
      html, body { background: #fff; }
      .page { margin: 0; box-shadow: none; }
    }
  </style>
</head>
<body>${pages}</body>
</html>`;
}
